function durations(route,story=false){const d=data.routes.find(r=>r.id===route)?.duration;if(!d)return [];return(d.values||Array.from({length:Math.max(0,Math.min(d.max,story?60:15)-d.min+1)},(_,i)=>d.min+i)).filter(n=>story||n<=15);}
