function mappedSlots(p){if(p.mapping==='one-to-one')return Array.from({length:p.count},(_,i)=>p.imageIds[i]?[p.imageIds[i]]:[]);if(p.mapping==='custom')return(p.rows||[]).flatMap(r=>Array.from({length:Number(r.count)||0},()=>r.imageId?[r.imageId]:[]));if(p.mapping==='shots')return Array.from({length:p.count},(_,i)=>p.shotImages?.[i]||[]);return Array.from({length:p.count},()=>p.imageIds[0]?[p.imageIds[0]]:[]);}
