  if(['complete','error'].includes(task.status))localStorage.removeItem('studio:draft:'+project.id);
  else localStorage.setItem('studio:draft:'+project.id,id);
  if(view==='prompts'&&(changed||task.status!=='running')){const y=scrollY;project=current;if(task.status==='complete')await applyGenerationPreset(false);renderStudio();scrollTo(0,y);}
