function projectMedia(p){
 const generated=new Set((data.imageTasks||[]).filter(t=>t.projectId===p.id).flatMap(t=>t.items.map(i=>i.referenceIdResult).filter(Boolean)));
 for(const asset of data.assets)if(asset.projectId===p.id&&asset.type==='generated')generated.add(asset.id);
 const ids=new Set([p.commonImageId,...Object.values(p.materials||{}).flat(),...p.plans.flatMap(plan=>[...(plan.imageIds||[]),...(plan.rows||[]).map(r=>r.imageId),...(plan.shotImages||[]).flat()]),...generated].filter(Boolean));
 return {assets:data.assets.filter(a=>ids.has(a.id)&&['upload','generated'].includes(a.type)),generated};
}
