    const byTemplate=new Map();for(const entry of groups){const j=entry[1][0],key=j.templateId||[j.skillId||'historical',j.actionTemplate?.id||'',j.templateName||j.actionTemplate?.name||'历史未分类'].join(':');if(!byTemplate.has(key))byTemplate.set(key,[]);byTemplate.get(key).push(entry);}
    $('workGroups').innerHTML=[...byTemplate].map(([key,projects],templateIndex)=>{const all=projects.flatMap(([,jobs])=>jobs),first=all[0];return `<details class="template-cluster ${projects.length===1?'single-template':''}" data-template-cluster="${esc(key)}" ${(projects.length===1|| (workUI.templateOpen?workUI.templateOpen.has(key):templateIndex<2))?'open':''}><summary><h2>${esc(first.templateName||first.actionTemplate?.name||'历史未分类')} <span class="badge">${all.length} 条 · ${projects.length} 个项目 / 历史批次</span></h2><span class="badge">${all.filter(j=>j.status==='complete'&&j.outputs?.length).length} 已完成 · ${all.filter(j=>j.status==='error').length} 失败</span><button data-template-download="${esc(key)}">下载该模板已完成作品</button></summary>${projects.map((entry,i)=>renderProjectGroup(entry,templateIndex+i)).join('')}</details>`;}).join('')||'<div class="empty">没有符合条件的作品。制作任务提交后会出现在这里。</div>';
