async function saveWorkFavorites(ids,add=true){const current=await api('/workspace-state'),favorite=new Set(current.favorite||[]);for(const id of ids)add?favorite.add('video:'+id):favorite.delete('video:'+id);const saved=await api('/workspace-state',{method:'PUT',body:{favorite:[...favorite]}});workFavorites=new Set(saved.favorite||[]);toast(add?'作品已收藏':'已取消收藏');}
function workBottom(){const all=visibleWorkIds.length&&visibleWorkIds.every(id=>selectedWorks.has(id));bottom(`<div class="work-selection"><label><input id="selectVisibleWorks" type="checkbox" ${all?'checked':''} ${!visibleWorkIds.length?'disabled':''}>已选 ${selectedWorks.size} 条</label><button id="downloadSelected" class="text-button" ${!selectedWorks.size?'disabled':''}>↓ 下载 ${selectedWorks.size} 条</button><button id="favoriteSelected" class="text-button" ${!selectedWorks.size?'disabled':''}>☆ 收藏</button></div><span class="work-total">共 ${document.querySelectorAll('.work').length} 条作品</span>`);$('selectVisibleWorks').indeterminate=!all&&visibleWorkIds.some(id=>selectedWorks.has(id));$('selectVisibleWorks').onchange=e=>{for(const id of visibleWorkIds)e.target.checked?selectedWorks.add(id):selectedWorks.delete(id);document.querySelectorAll('[data-work-check]').forEach(c=>c.checked=selectedWorks.has(c.dataset.workCheck));workBottom();};$('downloadSelected').onclick=()=>downloadWorks([...selectedWorks]);$('favoriteSelected').onclick=async()=>{try{$('favoriteSelected').disabled=true;await saveWorkFavorites([...selectedWorks]);await worksPage();}catch(e){toast(e.message);workBottom();}};}
async function downloadWorks(ids){try{const run=await post('/studio/downloads',{jobIds:ids,requestId:crypto.randomUUID()});modal(`<h2>准备作品下载</h2><p id="downloadState">正在保存 ${run.total} 条成片到本机…${run.excluded?'已排除 '+run.excluded+' 条未完成作品。':''}</p><a id="archiveLink" class="button primary" hidden>下载作品 ZIP</a>`);async function poll(){const state=await api('/studio/downloads/'+run.id);if($('downloadState'))$('downloadState').textContent=`已保存 ${state.complete}/${state.total} 条。${state.errors.map(e=>e.message).join('；')}`;if(state.ready&&$('archiveLink')){$('archiveLink').hidden=false;$('archiveLink').href='/api/studio/downloads/'+run.id+'/archive';}else if(state.running)setTimeout(poll,2500);}poll();}catch(e){toast(e.message);}}
function workStatusLabel(j){return j.status==='complete'&&!j.outputs?.length?'待获取成片地址':statusNames[j.status]||j.status;}
