async function init(){try{
  window.StudioShell?.mount();
  data=await api('/studio');
  if(page==='/studio'&&params.has('new')){projectChooser();return;}
  if(page==='/projects'){await projectsPage();return;}if(page==='/templates'){templateCenter();return;}if(page==='/assets'){assetsPage();return;}if(page==='/works'){if(params.get('project')&&!params.has('legacyLayout')&&!params.has('materials')&&data.projects.find(p=>p.id===params.get('project'))?.templateTypeId==='footspa:monitor'){location.replace('/studio?project='+encodeURIComponent(params.get('project'))+'#results');return;}await worksPage();if(params.get('video')){const job=works.find(j=>j.id===params.get('video'));if(job)workDetail(job);}return;}if(page==='/accounts'){await accountsPage();return;}if(page==='/settings'){await settingsPage();return;}
  if(params.has('type')&&!data.templateTypes.some(t=>t.id===params.get('type')))throw Error('模板类型不存在或已归档，请返回模板中心重新选择。');if(params.has('template')&&!data.templates.some(t=>t.id===params.get('template')&&!t.archived))throw Error('动作不存在或已归档，请返回模板中心重新选择。');
  scene=params.get('scene');const requestedType=data.templateTypes.find(t=>t.id===params.get('type'))||data.templateTypes.find(t=>params.get('template')&&t.actionIds.includes(params.get('template')))||data.templateTypes.find(t=>scene&&t.industryId===scene);scene=requestedType?.scene||scene;if(!scene&&!requestedType&&!params.get('template')&&!params.get('project')){home();return;}
  project=params.get('project')?await api('/studio/projects/'+params.get('project')):await post('/studio/projects',{videoDirection:requestedType?.categoryId==='service'?(params.get('direction')||''):'',templateTypeId:requestedType?.id,industryId:requestedType?.industryId,scene:scene||'',name:params.get('name')||(requestedType?.name||data.scenes.find(s=>s.id===scene)?.name||'模板')+'制作',plans:[]});
  scene=project.scene;
  if(!project.templateTypeId){const legacyType=data.templateTypes.find(t=>t.scene===scene&&project.plans.every(p=>t.actionIds.includes(p.templateId)));if(legacyType){project.templateTypeId=legacyType.id;project.industryId=legacyType.industryId;await save();}}
  if(!params.has('project')){const url=new URL(location.href);url.searchParams.set('project',project.id);history.replaceState(null,'',url);}
  if(params.get('template')&&!project.plans.length){const t=templateById(params.get('template'));if(t){scene=t.scene;project.scene=scene;const route=data.routes.find(r=>r.id===(generationChoice?.videoRoute||data.settings.defaultRoute||'doubao'));project.plans.push({id:crypto.randomUUID(),templateId:t.id,count:1,duration:t.duration,videoRoute:route.id,resolution:generationChoice?.resolution||route.resolutions[0],ratio:generationChoice?.ratio==='auto'?'9:16':generationChoice?.ratio||'9:16',referenceMode:generationChoice?.referenceMode||'first-frame',mapping:project.defaultMapping||t.mapping,imageIds:localStorage.getItem('studio:pendingAssetIds')?JSON.parse(localStorage.getItem('studio:pendingAssetIds')):localStorage.getItem('studio:pendingAsset')?[localStorage.getItem('studio:pendingAsset')]:project.commonImageId?[project.commonImageId]:[],rows:[],shotImages:[],creativeBrief:'',content:'',snapshot:t,prompts:[]});await save();}}
  if(params.get('brand')){const brand=assetById(params.get('brand'));if(brand?.type==='brand'){project.brandName=brand.name;project.brandFacts=brand.materials;await save();}}
  if(project.templateTypeId==='footspa:monitor'&&!params.has('legacyLayout')&&!params.has('materials')){view='prompts';renderStudio();return;}view=project.stage||'templates';renderStudio();const draftId=localStorage.getItem('studio:draft:'+project.id)||project.promptTaskId;if(draftId){const task=await api('/studio/drafts/'+draftId);draftState=task;if(!['complete','error'].includes(task.status)){localStorage.setItem('studio:draft:'+project.id,draftId);view='prompts';renderStudio();}await pollDraft(draftId);}const imageTask=localStorage.getItem('studio:images:'+project.id)||data.imageTasks?.find(t=>t.projectId===project.id&&t.status==='running')?.id;if(imageTask)pollImages(imageTask);
}catch(e){$('app').innerHTML=`<div class="notice warning">${esc(e.message)}</div>`;}}
window.addEventListener('pagehide',()=>{if(projectRevision<=savedRevision||promptDraftRunning()||window.monitorPipelineDrafting)return;if(project?.id){const snapshot=structuredClone(project);for(const p of snapshot.plans){delete p.snapshot.versions;delete p.prompts;}navigator.sendBeacon('/api/studio/projects',new Blob([JSON.stringify(snapshot)],{type:'application/json'}));}if(project?.id&&!promptDraftRunning()&&project.plans.length&&project.plans.every(p=>p.prompts.length===p.count&&p.prompts.every(Boolean)))navigator.sendBeacon(`/api/studio/projects/${project.id}/prompts`,new Blob([JSON.stringify({plans:project.plans.filter(p=>completePrompts(p)).map(p=>({id:p.id,prompts:p.prompts,scriptConfirmed:p.scriptConfirmed}))})],{type:'application/json'}));});
