function typeCard(t){return `<article class="type-card" data-type-card="${esc(t.id)}"><div class="type-cover"><img src="${esc(t.image)}" alt="${esc(t.name)}示意"><span>${t.special?'行业特色':'制作方案'}</span></div><div class="type-copy"><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><div class="type-meta"><span class="type-industry">${esc(industryName(t.industryId))}</span><span>${esc(t.categoryName||t.name)}</span><span>${t.workflowOnly?'人物、商品与口播':t.actionIds.length+' 个可选动作'}</span><span>${esc(t.materials)}</span></div>${workflowRecipeLinks(data.templateGroups.find(g=>g.variantIds.includes(t.id)),t.industryId)}<div class="type-buttons"><button data-type-detail="${esc(t.id)}">查看详情</button><a class="button primary" href="${typeUrl(t)}">${t.workflowOnly?'选择行业查看流程':'使用此模板'}</a></div></div></article>`;}
function bindWorkflowRecipeLinks(){document.querySelectorAll('[data-recipe-link]').forEach(b=>{b.classList.toggle('active',project?.videoDirection===b.dataset.recipeLink);b.onclick=()=>{const group=data.templateGroups.find(g=>g.workflowRecipes?.some(r=>r.id===b.dataset.recipeLink));if(!group)return;if(project&&group.id==='common:service'){project.videoDirection=b.dataset.recipeLink;invalidate();save().catch(()=>{});document.querySelectorAll('[data-recipe-link]').forEach(el=>el.classList.toggle('active',el.dataset.recipeLink===project.videoDirection));renderBottom();toast('视频方向已应用到当前项目。');return;}location.assign(sharedGroupUrl(group,b.dataset.recipeIndustry||'')+'&direction='+encodeURIComponent(b.dataset.recipeLink));};});}function bindTypeDetails(){document.querySelectorAll('[data-type-detail]').forEach(b=>b.onclick=()=>showTypeDetail(typeById(b.dataset.typeDetail)));bindWorkflowRecipeLinks();}
function showTypeDetail(t){if(!t)return;const group=data.templateGroups.find(g=>g.variantIds.includes(t.id));if(group?.workflowRecipes?.length){showSharedTypeDetail(group,t.industryId);return;}modal(`<h2>模板详情</h2><h3>${esc(t.name)} <span class="badge">${t.special?'行业特色':'完整制作方案'}</span></h3><img class="big-preview" src="${esc(t.image)}" alt="方案示意"><p class="muted">示意图片；动作示例可在制作台查看。</p><div class="type-detail-line"><strong>适用行业</strong><span>${esc(industryName(t.industryId))}</span></div><div class="type-detail-line"><strong>需要准备</strong><span>${esc(t.materials)}</span></div><p>${esc(t.description)}</p><h3>模板内动作 · ${t.actionIds.length} 个</h3><div class="action-chips">${t.actionIds.map(id=>`<span>${esc(templateById(id)?.name||id)}</span>`).join('')}</div><p class="notice">一个项目只对应一个模板类型。每个动作分别生成视频，可单独设置数量、时长和素材。</p><a class="button primary full-width" href="${typeUrl(t)}">使用此模板创建项目</a>`,true);}
function home(){
 $('app').className='home-page catalog-home';$('breadcrumb').textContent='首页';
 let chosen=localStorage.getItem('studio:industry')||'',goal='all';if(!data.industries.some(i=>i.id===chosen))chosen='';
 $('app').innerHTML=`<section class="industry-hero"><div><h1><em>为你的行业，</em>批量制作获客视频</h1><p>选行业与模板类型，在项目内配置动作与素材。</p><div class="hero-buttons"><button id="startIndustry" class="primary">＋ 新建制作项目</button><button id="resumeProject">◷ 继续上次项目</button></div></div><div class="hero-stack" aria-hidden="true"><span>▧</span><span>▷</span><span>↗</span></div></section><section class="industry-picker"><h2>选择你的行业</h2><div class="industry-chips">${data.industries.filter(i=>i.id!=='general').map(i=>`<button data-industry="${i.id}">${esc(i.name)}</button>`).join('')}</div></section><section id="industryTypes"><div class="type-section-heading"><div><h2 id="industryTypeTitle"></h2><p>选择一种模板类型，创建制作项目。</p></div><div class="goal-chips">${goals.map(g=>`<button data-goal="${g.id}">${g.name}</button>`).join('')}</div></div><div id="homeTypes" class="home-type-grid"></div></section><h2 class="section-label">实用工具</h2><div class="home-tools catalog-tools"><a href="/replicate?upload=1">${navIcon('replicate')}<div><strong>爆款复刻</strong><small>从参考视频提炼自己的制作方案</small></div><span>›</span></a><button id="homeAi">${navIcon('assets')}<div><strong>AI生成素材</strong><small>选择项目后，为动作准备专属素材</small></div><span>›</span></button><a href="/assets">${navIcon('assets')}<div><strong>我的素材</strong><small>管理与复用图片、视频、品牌资料</small></div><span>›</span></a></div><div class="section-heading"><h2>最近项目</h2><a class="button text-button" href="/projects">查看全部项目 →</a></div><div class="recent-projects">${data.projects.slice(0,4).map(p=>`<a href="/projects?project=${p.id}"><div><strong>${esc(p.name)}</strong><p>${esc(industryName(p.industryId||p.scene))} · ${esc(typeById(p.templateTypeId)?.name||'历史项目')} · ${p.plans.length} 个动作</p></div><span>打开项目 →</span></a>`).join('')||'<div class="empty">选择行业与模板类型，开始第一个项目。</div>'}</div>`;
 const render=()=>{document.querySelectorAll('[data-industry]').forEach(b=>b.classList.toggle('active',b.dataset.industry===chosen));document.querySelectorAll('[data-goal]').forEach(b=>b.classList.toggle('active',b.dataset.goal===goal));$('industryTypeTitle').textContent=chosen?industryName(chosen)+' · 模板类型':'先选择你的行业';$('homeTypes').innerHTML=chosen?data.templateTypes.filter(t=>t.industryId===chosen&&(goal==='all'||t.goal===goal)).map(typeCard).join('')||'<div class="empty">该行业暂没有符合此目标的方案，请更换筛选条件。</div>':'<div class="industry-empty"><span>▦</span><h3>从你的行业开始</h3><p>选择上方行业，查看适用的模板类型。</p></div>';document.querySelector('.goal-chips').hidden=!chosen;bindTypeDetails();};
 document.querySelectorAll('[data-industry]').forEach(b=>b.onclick=()=>{chosen=b.dataset.industry;goal='all';localStorage.setItem('studio:industry',chosen);render();});document.querySelectorAll('[data-goal]').forEach(b=>b.onclick=()=>{goal=b.dataset.goal;render();});$('startIndustry').onclick=()=>location.assign('/studio?new=1');$('resumeProject').onclick=()=>data.projects.length?location.assign('/studio?project='+data.projects[0].id):toast('先选择行业和模板类型创建项目。');$('homeAi').onclick=()=>{if(project?.id&&project.plans.length){imageWorkbench(project.plans[0],'generate');return;}toast('请先选择行业和模板类型，进入项目后生成素材。');$('industryTypes').scrollIntoView({behavior:'smooth'});};render();
}
function templateCenter(){
 $('app').className='template-center catalog-center';$('breadcrumb').textContent='模板中心';let industry=params.get('industry')||'',category='',source='all',goal='all',search='';
 const render=()=>{$('app').innerHTML=`<div class="catalog-page-head"><div><h1>模板中心</h1><p>按行业选择完整制作方案，动作在模板内配置。</p></div><input id="catalogSearch" placeholder="搜索行业或模板类型" value="${esc(search)}"><button id="createType">＋ 新建模板</button></div><div class="catalog-layout"><aside class="catalog-filters"><h3>行业</h3>${[{id:'',name:'全部行业'},...data.industries].map(i=>`<button data-catalog-industry="${i.id}" class="${industry===i.id?'active':''}">${esc(i.name)}</button>`).join('')}<hr><h3>模板类型</h3>${[{id:'',name:'全部类型'},...(data.templateCategories||[])].map(c=>`<button data-catalog-category="${c.id}" class="${category===c.id?'active':''}">${esc(c.name)}</button>`).join('')}<hr><h3>获客目标</h3>${goals.map(g=>`<button data-catalog-goal="${g.id}" class="${goal===g.id?'active':''}">${g.name}</button>`).join('')}</aside><section class="catalog-results"><div class="source-tabs">${[{id:'all',name:'全部'},{id:'builtin',name:'内置'},{id:'my',name:'我的'},{id:'replica',name:'复刻生成'}].map(v=>`<button data-catalog-source="${v.id}" class="${source===v.id?'active':''}">${v.name}</button>`).join('')}</div><div id="catalogCards" class="catalog-card-grid"></div></section></div>`;renderCards();$('catalogSearch').oninput=e=>{search=e.target.value;renderCards();};document.querySelectorAll('[data-catalog-industry]').forEach(b=>b.onclick=()=>{industry=b.dataset.catalogIndustry;render();});document.querySelectorAll('[data-catalog-category]').forEach(b=>b.onclick=()=>{category=b.dataset.catalogCategory;render();});document.querySelectorAll('[data-catalog-source]').forEach(b=>b.onclick=()=>{source=b.dataset.catalogSource;render();});document.querySelectorAll('[data-catalog-goal]').forEach(b=>b.onclick=()=>{goal=b.dataset.catalogGoal;render();});$('createType').onclick=createType;};
   const renderCards=()=>{$('catalogCards').innerHTML=(data.templateGroups||[]).filter(g=>(!industry||g.industryIds.includes(industry))&&(!category||g.categoryId===category)&&(source==='all'||g.source===source)&&(goal==='all'||g.goal===goal)&&(g.name+g.description+g.industryIds.map(industryName).join(' ')+(g.workflowRecipes||[]).map(r=>r.name).join(' ')).includes(search)).map(g=>sharedTypeCard(g,industry)).join('')||'<div class="empty">没有符合条件的模板类型。</div>';document.querySelectorAll('[data-group-detail]').forEach(b=>b.onclick=()=>showSharedTypeDetail(data.templateGroups.find(g=>g.id===b.dataset.groupDetail),industry));bindWorkflowRecipeLinks();};render();
}
function createType(){modal(`<h2>新建模板</h2><p>定义一个完整方案，并添加它的第一个动作。后续可在制作台继续添加动作。</p><form id="createTypeForm"><label class="field">行业<select name="industry" required><option value="" disabled selected>请选择行业</option>${options(data.industries.filter(i=>i.id!=='general'))}</select></label><label class="field">模板名称<input name="name" required maxlength="80" placeholder="例如：新品展示"></label><label class="field">第一个动作<input name="actionName" required maxlength="80"></label><label class="field">动作与内容<textarea name="description" required></textarea></label><label class="field">素材要求<textarea name="materials" required></textarea></label><button type="submit" class="primary">保存模板</button></form>`);$('createTypeForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),id='custom:'+crypto.randomUUID();try{await post('/studio/templates',{name:f.get('actionName'),description:f.get('description'),actions:[f.get('description')],scene:f.get('industry'),industryId:f.get('industry'),catalogType:id,catalogName:f.get('name'),imageRules:f.get('materials'),mapping:'common'});data=await api('/studio');$('modal').close();templateCenter();toast('模板已保存，可进入项目选择或新增动作。');}catch(error){toast(error.message);}};}
function renderGenerationControls(container){
 const section=document.createElement('section');section.className='project-generation-settings';section.innerHTML=generationSettingsMarkup(projectRoutes(),generationChoice,esc);container.append(section);
 const hint=()=>{const route=data.routes.find(r=>r.id===generationChoice.videoRoute);$('modelDurationHint').textContent=`支持时长：${route.duration.values?route.duration.values.join('、'):route.duration.min+'–'+route.duration.max}秒。${route.id==='doubao'?'画质由豆包服务决定。':route.id==='tokendance-seedance-2.5'?'Seedance 2.5不支持直接上传真人人脸参考。':''}`;document.querySelectorAll('[data-video-duration]').forEach(el=>{const plan=selectedPlan(el.dataset.videoDuration),values=durations(route.id,scene==='story');el.innerHTML=(!values.includes(plan.duration)?`<option value="${plan.duration}">${plan.duration}秒（不支持，请修改）</option>`:'')+options(values,plan.duration);});};hint();
 for(const [id,key]of [['projectVideoRoute','videoRoute'],['projectVideoModel','videoRoute'],['projectRatio','ratio'],['projectResolution','resolution'],['projectReferenceMode','referenceMode']])$(id).onchange=async e=>{const cleanIds=project.plans.filter(p=>completePrompts(p)&&!p.promptsDirty).map(p=>p.id);generationChoice[key]=e.target.value;if(key==='videoRoute'){const route=data.routes.find(r=>r.id===e.target.value);generationChoice.resolution=route.resolutions.includes('720P')?'720P':route.resolutions[0];$('projectResolution').innerHTML=options(route.resolutions,generationChoice.resolution);$('projectVideoRoute').value=serviceId(projectRoutes(),route.id);$('projectVideoModel').innerHTML=options(modelRoutes(projectRoutes(),route.id).map(r=>({id:r.id,name:r.model})),route.id);}localStorage.setItem('studio:generationPreset',JSON.stringify(generationChoice));if(promptDraftRunning()||window.monitorPipelineDrafting){if(window.monitorPipelineDrafting){try{await window.monitorUpdateSettings?.(generationChoice);}catch(err){toast(err.message);return;}}hint();toast('视频设置已调整，提示词继续生成；提交视频时使用新设置。');return;}try{await applyGenerationPreset(false);document.querySelectorAll('[data-prompt],[data-line-prompt]').forEach(el=>{const [id,index]=(el.dataset.prompt||el.dataset.linePrompt).split(':');const start=el.selectionStart,end=el.selectionEnd;el.value=selectedPlan(id).prompts[index]||'';if(document.activeElement===el)el.setSelectionRange(start,end);});await save();if(cleanIds.length){await post(`/studio/projects/${project.id}/prompts`,{confirm:true,plans:project.plans.filter(p=>cleanIds.includes(p.id)).map(p=>({id:p.id,prompts:p.prompts,scriptConfirmed:p.scriptConfirmed}))});}hint();if(view==='templates'){renderTemplateGrid();renderBottom();}else updatePromptProductionControls();}catch(err){toast(err.message);}};
}
function renderMonitorWarning(container){
 if(project.templateTypeId!=='footspa:monitor')return;const ids=[...new Set(project.plans.flatMap(p=>mappedSlots(p).flat()))];if(!ids.length||ids.every(id=>assetById(id)?.monitorView))return;
 const note=document.createElement('div');note.className='notice warning';note.id='monitorViewWarning';note.innerHTML='<strong>底图尚未标记为监控首帧</strong><p>普通上传图不会自动变成高位监控画面。视频提示词不能替代首帧的机位调整；建议先按模拟监控视角生成底图，再生成视频。</p><button id="prepareMonitorFrame">生成监控首帧</button><button id="confirmMonitorFrame">我的底图已是监控视角</button>';container.append(note);$('prepareMonitorFrame').onclick=()=>imageWorkbench(project.plans[0]);$('confirmMonitorFrame').onclick=async()=>{try{for(const id of ids)await api('/studio/assets/'+id,{method:'PATCH',body:{monitorView:true}});data=await api('/studio');note.remove();toast('已记录你对底图监控机位的确认。');}catch(e){toast(e.message);}};
}
function renderStudio(){ensureGenerationPreset();if(promotionCategory(project)&&!params.has('legacyLayout')&&!params.has('materials')){renderPromotionStudio({project,data,app:$('app'),esc,api,post,save,toast,modal,closeModal:()=>$('modal').close(),pickAsset:chooseCommonAsset,uploadAsset:uploadImage,rerender:async()=>{const y=scrollY;data=await api('/studio');renderStudio();scrollTo(0,y);}});return;}if(project?.templateTypeId==='footspa:monitor'&&!params.has('legacyLayout')&&!params.has('materials')){view='prompts';$('breadcrumb').textContent='项目 / '+project.name;renderMonitorStudio({project,data,app:$('app'),esc,api,post,save,settings:renderGenerationControls,applySettings:()=>applyGenerationPreset(true),persistPrompts,choice:generationChoice,modal,closeModal:()=>$('modal').close(),updateCatalog:value=>{data=value;},rerender:async()=>{const y=scrollY,selected=document.activeElement?.dataset?.lineAction;data=await api('/studio');renderStudio();if(selected)document.querySelector(`[data-line-action="${CSS.escape(selected)}"]`)?.focus({preventScroll:true});scrollTo(0,y);}});return;}legacyRenderStudio();if(view==='templates')enhanceProduction();else{const type=projectType();$('breadcrumb').textContent=`${industryName(project.industryId||scene)} / ${type.name} / 提示词与视频`;$('templateTab').textContent='‹ 上一步：动作与素材';}if(view==='prompts'){const holder=document.createElement('div');$('studioContent').prepend(holder);renderGenerationControls(holder);renderMonitorWarning(holder);document.querySelectorAll('[data-video-duration]').forEach(el=>el.onchange=async()=>{const plan=selectedPlan(el.dataset.videoDuration);plan.duration=Number(el.value);invalidate(plan);await save();renderStudio();});updatePromptProductionControls();}renderProductionProgress();}
function enhanceProduction(){
 if(!$('studioContent'))return;
 const type=projectType();$('app').classList.add('catalog-production');$('breadcrumb').innerHTML=`<a href="/studio">首页</a> / 批量制作 / ${esc(industryName(project.industryId||scene))}`;
 $('app').querySelector('h1').textContent=project.name;$('app').querySelector('.lead').innerHTML=`<span class="project-context">行业：${esc(industryName(project.industryId||scene))}</span><span class="project-context">模板类型：${esc(type.name)}</span><span class="project-rule">一个项目 · 一个模板类型</span>`;
 const controls=document.querySelector('.studio-header-actions');controls.querySelector('#templateTab').hidden=true;controls.querySelector('#promptTab').textContent='下一步：提示词与视频 →';const flow=document.createElement('div');flow.className='project-flow';flow.innerHTML='<strong>① 动作与素材</strong><i></i><span>② 提示词与视频</span>';controls.prepend(flow);
 const split=document.createElement('div');split.className='production-workspace';const left=document.createElement('section');left.className='material-workspace';const right=document.createElement('section');right.className='action-workspace';
 left.innerHTML='<h2>素材与内容</h2><p class="muted">为所选动作准备素材，已有素材保存在本机。</p>';
 const source=$('app').querySelector('.sourcebar');
 if(source&&scene!=='story'){
   const actions=document.createElement('div');actions.className='material-import';for(const [id,label]of [['commonUpload','上传素材'],['commonGenerate','AI生成素材'],['commonAssets','我的素材']]){const b=$(id);b.textContent=label;actions.append(b);}left.append(actions);
   const preview=$('commonPreview');preview.classList.add('material-preview');left.append(preview);const asset=assetById(project.commonImageId||project.plans.find(p=>p.mapping==='common')?.imageIds[0]);const meta=document.createElement('div');meta.className='material-meta';meta.innerHTML=asset?`<strong>${esc(asset.name)}</strong><span>${asset.confirmed===false?'待确认素材':'已确认素材'}</span>`:'<strong>尚未选择素材</strong><span>上方图片仅为场景示意，请上传或选择真实素材。</span>';left.append(meta);const mapping=$('commonMapping');const label=document.createElement('label');label.className='field';label.textContent='素材绑定方式';label.append(mapping);left.append(label);source.remove();
   const brief=document.createElement('div');brief.innerHTML=`<label class="field">人物描述<input id="projectPeople" value="${esc(project.peopleBrief||'')}" placeholder="例如：成年服务人员，自然得体穿搭"></label><label class="field">整批内容补充（可选）<textarea id="projectContent" placeholder="填写真实产品卖点或整批要求">${esc(project.contentBrief||'')}</textarea></label>`;left.append(brief);
 }else if(source){left.append(source);}else{left.innerHTML+='<p>先选择一个动作，再为它准备素材。</p>';}
 const content=$('studioContent');right.innerHTML=`<div class="action-workspace-head"><h2>动作与生成计划</h2><p>同一模板内选择多个动作，每个动作分别生成视频。</p><span id="actionSummary">已选 ${project.plans.length} 个动作</span></div>`;right.innerHTML+=workflowRecipeLinks(data.templateGroups.find(g=>g.variantIds.includes(type.id)),project.industryId);right.append(content);
 content.querySelector('#templateSearch').placeholder='搜索此模板内的动作';content.querySelector('#newTemplate').textContent='＋ 新增动作';
 split.append(left,right);$('app').append(split);renderGenerationControls(right);renderMonitorWarning(left);
 if($('projectPeople'))$('projectPeople').oninput=e=>{project.peopleBrief=e.target.value;for(const p of project.plans){p.snapshot.people=e.target.value||'自然得体的成年人';invalidate(p);}delayedSave();};if($('projectContent'))$('projectContent').oninput=e=>{project.contentBrief=e.target.value;for(const p of project.plans){p.creativeBrief=e.target.value;invalidate(p);}delayedSave();};
 renderCreativeMaterials();bindWorkflowRecipeLinks();
 renderBottom();
}
function showFootspaReferences(template){
 const reference=template?primaryActionReference(template):null;const clips=template?(reference?[reference]:[]):data.footspaReferenceClips||[];
 const card=c=>`<article class="reference-clip"><div class="reference-media">${c.videoUrl?`<video controls playsinline preload="none" poster="${esc(c.posterUrl)}" src="${esc(c.videoUrl)}" aria-label="${esc(c.title)}"></video>`:`<div class="reference-placeholder">${c.source?'原作在抖音查看':'暂无本地预览'}<small>媒体未导入当前设备</small></div>`}</div><div class="reference-info"><span class="badge">${esc(c.group)}${c.duration?` · ${c.duration} 秒`:" · 抖音原作"}</span><h3>${esc(c.title)}</h3><div class="reference-link-slot">${c.source?`<a class="button douyin-origin-link" href="${esc(c.source.url)}" target="_blank" rel="noopener noreferrer">在抖音打开原作 ↗</a>`:'<span class="muted">原作链接未核实 · 可正常预览与制作</span>'}</div></div></article>`;
 modal(`<h2>${template?esc(template.name):'足浴监控 · 参考视频库'}</h2><p class="muted">参考用于理解动作；制作时保留你的门店与人物。部分原片短于5秒或长于8秒，模板会精简为一个核心动作。</p>${template?`<button id="referencePrompt" class="primary">查看本动作提示词</button>`:''}<div class="reference-grid">${clips.map(card).join('')||`<div class="reference-empty"><strong>这个动作暂无参考视频</strong><p>保留动作规则与结束状态，可以正常准备底图并制作视频。</p><img src="${exampleImage(template)}" alt="场景示意，并非原作视频"></div>`}</div>${template?.example?.videoUrl?`<details class="detail-block"><summary>查看项目内已生成的示例</summary><video controls preload="none" class="big-preview" src="${esc(template.example.videoUrl)}"></video></details>`:''}${!template?`<details class="reference-source-list"><summary>查看全部 ${data.footspaSources?.length||0} 个抖音原作链接（含尚未对应的来源）</summary><p class="muted">以下是你提供的来源清单，未确认对应关系的来源不会冒充某个本地视频的原作。</p>${(data.footspaSources||[]).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a>`).join('')}</details>`:''}`);
 if($('referencePrompt'))$('referencePrompt').onclick=()=>showFootspaPrompt(template);document.querySelectorAll('[data-reference-prompt]').forEach(b=>b.onclick=()=>showFootspaPrompt(data.templates.find(t=>t.packId==='foot-spa-store'&&t.actionId===b.dataset.referencePrompt)));
 const dialog=$('modal');dialog.addEventListener('close',()=>dialog.querySelectorAll('video').forEach(v=>v.pause()),{once:true});
}
async function showFootspaPrompt(template){
 const plan=project?.plans?.find(p=>p.templateId===template.id);
 modal(`<h2>${esc(template.name)} · 动作提示词</h2><p class="muted">用于验收模板内容，调整时长或人物参考后重新预览；不会提交视频生成。</p><div class="prompt-review-controls"><label>时长<select id="previewPromptDuration">${options([5,6,7,8],plan?.duration&&[5,6,7,8].includes(plan.duration)?plan.duration:6)}</select></label><label>画幅<select id="previewPromptRatio">${options(['9:16','16:9','1:1'],plan?.ratio||'9:16')}</select></label><label>人物参考<select id="previewPromptIdentity">${options([{id:'none',name:'不上传，按模板生成'},{id:'reference',name:'使用上传的人物身份'}],project?.materials?.personImageIds?.length?'reference':'none')}</select></label></div><textarea id="footspaPromptText" class="footspa-prompt-text" readonly></textarea><div class="row"><button id="copyFootspaPrompt" class="primary">复制提示词</button><button id="exportFootspaPrompt">导出这一条</button></div>`);
 let revision=0;
 const refresh=async()=>{const current=++revision;try{const result=await api('/footspa-prompt',{method:'POST',body:{actionId:template.actionId,duration:Number($('previewPromptDuration').value),ratio:$('previewPromptRatio').value,personImages:$('previewPromptIdentity').value==='reference'}});if(current===revision&&$('footspaPromptText'))$('footspaPromptText').value=result.prompt;}catch(e){toast(e.message);}};
 for(const id of ['previewPromptDuration','previewPromptRatio','previewPromptIdentity'])$(id).onchange=refresh;
 $('copyFootspaPrompt').onclick=async()=>{try{await navigator.clipboard.writeText($('footspaPromptText').value);toast('提示词已复制');}catch{$('footspaPromptText').select();toast('已选中提示词，请复制');}};
 $('exportFootspaPrompt').onclick=()=>downloadPromptText(template.name,$('footspaPromptText').value);await refresh();
}
function downloadPromptText(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'_')+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function reviewFootspaPrompts(){
 const templates=data.templates.filter(t=>t.packId==='foot-spa-store'&&t.source==='builtin'&&!t.archived);
 modal(`<h2>足浴监控 · 模板提示词验收</h2><p class="muted">共 ${templates.length} 个动作，旧动作保留。逐条对照参考、起始站位与结束状态；只有外链的来源不虚构画面或动作。</p><div class="row"><button id="exportAllFootspaPrompts" class="primary">导出全部模板提示词</button></div><div class="prompt-acceptance-list">${templates.map(t=>`<article><div><strong>${esc(t.name)}</strong><small>${t.referenceClips?.length?'1 个原作参考':'暂无参考 · 保留原动作'} · ${esc(t.actionTemplate?.sceneTags?.includes('stairs')?'楼梯':t.actionTemplate?.sceneTags?.includes('reception_desk')?'前台':t.actionTemplate?.sceneTags?.includes('lobby')?'大厅':'走廊')}</small></div><button data-review-prompt="${esc(t.id)}">查看提示词</button></article>`).join('')}</div>`);
 document.querySelectorAll('[data-review-prompt]').forEach(b=>b.onclick=()=>showFootspaPrompt(templateById(b.dataset.reviewPrompt)));
 $('exportAllFootspaPrompts').onclick=async()=>{const button=$('exportAllFootspaPrompts');button.disabled=true;try{const parts=[];for(const t of templates){const v=await api('/footspa-prompt',{method:'POST',body:{actionId:t.actionId,duration:6,ratio:'9:16'}});parts.push(`## ${t.name}\n\n${v.prompt}\n\n${[primaryActionReference(t)].filter(c=>c?.source).map(c=>`参考原作：${c.source.url}`).join('\n')}`);}downloadPromptText('足浴监控全部模板提示词',parts.join('\n\n'));}catch(e){toast(e.message);}finally{button.disabled=false;}};
}

function generationChoiceReady(){return ['videoRoute','ratio','resolution','referenceMode'].every(k=>generationChoice?.[k]);}
function ensureGenerationPreset(){
 if(generationChoice||!project)return;let stored={};try{stored=JSON.parse(localStorage.getItem('studio:generationPreset')||'{}');}catch{}
 const routes=projectRoutes(),route=routes.find(r=>r.id===(project.plans[0]?.videoRoute||stored.videoRoute||data.settings.defaultRoute)&&r.referenceMode==='reference-image')||routes.find(r=>r.id==='wan-tokendance')||routes.find(r=>r.referenceMode==='reference-image')||routes[0];
 if(!route)return;generationChoice={videoRoute:route.id,resolution:route.resolutions.includes(project.plans[0]?.resolution)?project.plans[0].resolution:route.resolutions.includes(stored.resolution)?stored.resolution:route.resolutions.includes('720P')?'720P':route.resolutions[0],ratio:['auto','9:16','16:9','1:1'].includes(stored.ratio)?stored.ratio:'auto',referenceMode:['first-frame','reference-image'].includes(stored.referenceMode)?stored.referenceMode:'first-frame'};
}
async function applyGenerationPreset(resolveImages){
 ensureGenerationPreset();if(!generationChoiceReady())throw Error('没有可用的生成服务，请先配置服务。');
 for(const plan of project.plans){
   let ratio=generationChoice.ratio;plan.autoRatio=ratio==='auto';
   if(ratio==='auto'){
     ratio=plan.ratio||'9:16';const id=mappedSlots(plan)[0]?.[0]||project.commonImageId,asset=assetById(id);
     if(resolveImages&&asset?.previewUrl){const size=await new Promise(resolve=>{const img=new Image(),timer=setTimeout(()=>resolve(null),5000);img.onload=()=>{clearTimeout(timer);resolve([img.naturalWidth,img.naturalHeight]);};img.onerror=()=>{clearTimeout(timer);resolve(null);};img.src=asset.previewUrl;});if(size){const [w,h]=size;ratio=Math.abs(w-h)/Math.max(w,h)<.08?'1:1':w>h?'16:9':'9:16';}}
   }
   if(plan.ratio!==ratio)plan.prompts=(plan.prompts||[]).map(text=>text.replace(/\b(?:9:16|16:9|1:1)\b/g,ratio));
   Object.assign(plan,{...generationChoice,ratio});
 }
}
function renderVideoResultStatus(element,jobs,submitted=false){
 if(!element)return;const complete=jobs.filter(j=>j.status==='complete'&&j.outputs?.length),failed=jobs.filter(j=>j.status==='error'),pending=jobs.filter(j=>!['complete','error','cancelled','needs_review'].includes(j.status)),review=jobs.filter(j=>j.status==='needs_review'||j.status==='complete'&&!j.outputs?.length);
 element.innerHTML=`<strong>${!jobs.length?'视频尚未提交':complete.length===jobs.length?'视频已生成，可预览或下载':failed.length===jobs.length?'视频生成失败':pending.length?'视频任务正在处理':'视频任务处理结束'}</strong><div class="progress-facts"><span>已产出 ${complete.length} 条视频</span><span>处理中 ${pending.length}</span><span>失败 ${failed.length}</span>${review.length?`<span>需核对 ${review.length}（尚未取得成片）</span>`:''}</div>${submitted?'<p>提交已收到。任务提交成功不代表视频已经生成，结果会自动更新。</p>':''}${failed.length?`<p class="progress-error">失败原因：${esc(failed[0].error||'生成服务未返回原因')}</p>`:''}`;
}
function renderProductionProgress(){
 if(!project?.id||!$('studioContent'))return;const id=project.id;let panel=$('projectProductionStatus');if(!panel){panel=document.createElement('section');panel.id='projectProductionStatus';panel.className='production-progress';panel.setAttribute('aria-live','polite');$('app').querySelector('.studio-header-actions')?.after(panel);}
 const update=async()=>{try{const [overview,jobs]=await Promise.all([api('/studio'),api('/studio/works')]);if(project?.id!==id||!$('projectProductionStatus'))return;const p=overview.projects.find(p=>p.id===id)||project,images=overview.imageTasks.filter(t=>t.projectId===id).flatMap(t=>t.items),drafts=p.plans.reduce((n,p)=>n+(p.prompts?.length||0),0),mine=jobs.filter(j=>j.projectId===id);renderVideoResultStatus($('projectProductionStatus'),mine);$('projectProductionStatus').insertAdjacentHTML('beforeend',`<p>提示词：${drafts} 条已生成 · 底图：${images.filter(i=>i.status==='complete').length} 张已生成${images.some(i=>i.status==='error')?' · 有底图生成失败':''}</p><a class="button" href="/works?project=${encodeURIComponent(id)}">查看视频任务与成片 →</a>${mine.filter(j=>j.status==='error').map(j=>`<button data-project-retry="${esc(j.id)}">重试：${esc(j.templateName||'失败视频')}</button>`).join('')}`);document.querySelectorAll('[data-project-retry]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;await post('/studio/jobs/'+b.dataset.projectRetry+'/retry',{});toast('已恢复失败任务，成功的视频不会重做。');update();}catch(e){toast(e.message);b.disabled=false;}});}catch(e){if($('projectProductionStatus'))$('projectProductionStatus').textContent='无法更新制作状态：'+e.message;}};
 clearInterval(renderProductionProgress.timer);update();renderProductionProgress.timer=setInterval(update,5000);
}
function renderCreativeMaterials(){
 const left=document.querySelector('.material-workspace');if(!left)return;
 const type=projectType(),avatar=type.categoryId==='avatar-talk',massage=type.categoryId==='massage-care',product=type.categoryId==='service'||avatar,monitor=type.id==='footspa:monitor';
 if(!product&&!massage&&!monitor)return;
 project.materials||={productImageIds:[],personImageIds:[],sceneImageIds:[]};project.productBrief||={};project.massageSpec||={};
 document.getElementById('creativeMaterials')?.remove();const panel=document.createElement('section');panel.id='creativeMaterials';panel.className='creative-materials';
 const role=(id,name,hint)=>`<div class="material-role"><div><strong>${name}</strong><small>${hint}</small></div><div class="role-thumbs">${(project.materials[id]||[]).map(assetId=>`<div><img src="${esc(assetById(assetId)?.previewUrl||'')}" alt="${esc(name)}"><button data-remove-role="${id}" data-role-asset="${esc(assetId)}" aria-label="移除${esc(name)}">×</button></div>`).join('')}</div><div class="role-actions"><button data-upload-role="${id}">＋ 添加${name}</button><button data-pick-role="${id}">从素材选择</button></div></div>`;
 const brief=(key,label,placeholder,large=false)=>`<label class="field">${label}${large?`<textarea data-product-field="${key}" placeholder="${placeholder}">${esc(project.productBrief[key]||'')}</textarea>`:`<input data-product-field="${key}" placeholder="${placeholder}" value="${esc(project.productBrief[key]||'')}">`}</label>`;
 panel.innerHTML=monitor?`<h2>人物参考（可选）</h2><p class="muted">不上传也可以按动作模板生成成年人物；上传后先合成人物与门店的起始底图。</p>${role('personImageIds','人物图','选填，保持成年人物身份')}<p class="notice">选择门店底图与人物后，点击「AI生成素材」合成首帧，确认后再生成视频。参考视频只用于学习动作，不会直接作为生成底图。</p>`:product?`<h2>${avatar?'人物与商品口播':'产品与宣传内容'}</h2><p class="muted">产品、人物、场景分别保存，生成关键帧时组合，主体参考模式会随视频请求一起提交。</p>${role('productImageIds','产品图','保持真实包装、外观与材质')}${role('personImageIds','人物图',avatar?'保持讲解者身份；无人物图时可按描述生成':'选填，保持人物形象')}${role('sceneImageIds','场景图','选填，保持门店或使用场景')}${brief('name','产品名称','填写真实商品名称')}${brief('sellingPoints','已确认卖点','只填写真实且确认过的卖点',true)}${brief('script',avatar?'口播文案':'旁白文案（选填）','填写本条视频需要说出的内容',true)}${avatar?`<label class="field">口播方式<select id="avatarMode">${options([{id:'native',name:'模型生成口播'},{id:'audio-driven',name:'已有配音驱动口型'}],project.avatarMode||'native')}</select></label><p class="muted">模型口播由视频模型生成声音；使用已有配音时，时长由配音决定，需要专用对口型服务。</p><label class="field" id="audioUrlField" ${project.avatarMode!=='audio-driven'?'hidden':''}>配音文件地址<input id="avatarAudioUrl" placeholder="https://…/voice.mp3 或 voice.wav" value="${esc(project.audioUrl||'')}"></label>`:''}<details><summary>声音与配乐</summary>${brief('voice','声音要求','例如：自然、清晰、轻松的中文讲解')}${brief('music','背景音乐','例如：轻快、不盖过人声')}</details>`:`<h2>按摩护理要求</h2><p class="muted">使用包含成年服务人员和顾客的双人底图，核对姿态与接触部位。</p><label class="field">护理部位<select data-massage-field="bodyArea">${options(['按动作模板','肩颈','手臂','背部','足部','居家护理'],project.massageSpec.bodyArea||'按动作模板')}</select></label><label class="field">人物起始姿态<input data-massage-field="position" placeholder="例如：顾客坐姿，服务人员站在身后" value="${esc(project.massageSpec.position||'')}"></label><label class="field">手法与接触要求<textarea data-massage-field="contact" placeholder="明确双手位置、力度和连续动作要求">${esc(project.massageSpec.contact||'')}</textarea></label><p class="notice">每个护理动作分别制作，默认每条视频使用独立人物底图；不要把一张门店环境图直接当作护理起始画面。</p>`;
 left.prepend(panel);
 const applyRole=async(roleId,id)=>{project.materials[roleId]||=[];if(project.materials[roleId].length>=12){toast('每类最多选择12张素材');return;}if(!project.materials[roleId].includes(id))project.materials[roleId].push(id);invalidate();await save();renderCreativeMaterials();renderBottom();toast('素材已绑定到当前项目。');};
 panel.querySelectorAll('[data-upload-role]').forEach(b=>b.onclick=()=>uploadImage(ref=>applyRole(b.dataset.uploadRole,ref.id).catch(e=>toast(e.message))));
 panel.querySelectorAll('[data-pick-role]').forEach(b=>b.onclick=()=>chooseCommonAsset(id=>applyRole(b.dataset.pickRole,id).catch(e=>toast(e.message))));
 panel.querySelectorAll('[data-remove-role]').forEach(b=>b.onclick=()=>{project.materials[b.dataset.removeRole]=project.materials[b.dataset.removeRole].filter(id=>id!==b.dataset.roleAsset);invalidate();save().catch(()=>{});renderCreativeMaterials();renderBottom();});
 panel.querySelectorAll('[data-product-field]').forEach(el=>el.oninput=()=>{project.productBrief[el.dataset.productField]=el.value;invalidate();delayedSave();renderBottom();});
 panel.querySelectorAll('[data-massage-field]').forEach(el=>el.oninput=()=>{project.massageSpec[el.dataset.massageField]=el.value;invalidate();delayedSave();});
 if($('avatarMode'))$('avatarMode').onchange=e=>{project.avatarMode=e.target.value;invalidate();$('audioUrlField').hidden=e.target.value!=='audio-driven';delayedSave();};
 if($('avatarAudioUrl'))$('avatarAudioUrl').oninput=e=>{project.audioUrl=e.target.value;invalidate();delayedSave();};
}

function projectChooser(){
 $('app').className='project-chooser-page';$('breadcrumb').textContent='批量制作 / 创建项目';
 let requestedGroup=data.templateGroups?.find(g=>g.id===params.get('group')),industry='',selected='',autoName='';
 const supports=i=>i.id!=='general'&&(!requestedGroup||requestedGroup.industryIds.includes(i.id));
 const hinted=data.industries.find(i=>i.id===params.get('industry')&&supports(i));
 industry=hinted?.id||(requestedGroup?.industryIds.length===1?requestedGroup.industryIds[0]:'');
 const chooseIndustry=id=>{industry=id;selected=requestedGroup?.variantIds.find(v=>typeById(v)?.industryId===industry)||'';if(selected){autoName=industryName(industry)+requestedGroup.name+'制作';if(!$('newProjectName').value||$('newProjectName').value===autoName)$('newProjectName').value=autoName;else if(!$('newProjectName').dataset.edited)$('newProjectName').value=autoName;}localStorage.setItem('studio:industry',industry);render();};
 $('app').innerHTML=`<div class="chooser-heading"><div><span class="eyebrow">新建制作项目</span><h1>${requestedGroup?'确认行业 · '+esc(requestedGroup.name):'选择行业与模板类型'}</h1><p>确认行业后进入制作；在模板内配置视频方向、动作、素材与生成参数。</p></div><a href="/studio" class="button">返回首页</a></div><div class="chooser-progress"><span class="active">① 选择行业</span><i></i><span id="chooserStepType">② 确认模板类型</span><i></i><span>③ 进入制作台</span></div><section class="chooser-industries"><h2>你的行业</h2><div class="industry-chips" id="chooserIndustryChips"></div>${requestedGroup&&!requestedGroup.shared?'<p class="muted">此特色模板仅适用于上方行业。<a href="/studio?new=1">选择其他行业与通用模板 →</a></p>':'<form id="addIndustryForm" class="add-industry-form"><label for="newIndustryName">没有你的行业？输入新增</label><div><input id="newIndustryName" maxlength="30" placeholder="例如：宠物用品、汽车美容、服装"><button type="submit">＋ 添加行业</button></div><p id="industryFeedback" role="status">新行业可使用通用模板，保存后可在下次直接选择。</p></form>'}</section><section class="chooser-type-section"><div class="section-heading"><h2 id="chooserTypesTitle">选择模板类型</h2><p id="chooserTypesHint">先选择行业，再查看适用方案。</p></div><div id="chooserTypes" class="chooser-type-grid"></div></section><section class="chooser-project-details"><label class="field">项目名称<input id="newProjectName" maxlength="100" placeholder="选择模板类型后，可修改项目名称"></label><div id="chooserSelection" role="status">尚未选择行业与模板类型</div></section><div class="chooser-footer"><p>确认后进入制作，不会直接提交生成任务。</p><button id="enterProject" class="primary" disabled>选择行业与模板类型后继续</button></div>`;
 const update=()=>{const t=typeById(selected);$('enterProject').disabled=!t||(!t.workflowOnly&&!$('newProjectName').value.trim());$('enterProject').textContent=t?(t.workflowOnly?'查看制作流程 · 选择素材后即可制作':'创建项目并进入制作台 →'):'选择行业与模板类型后继续';$('chooserSelection').textContent=t?industryName(industry)+' / '+t.name:'尚未选择模板类型';$('newProjectName').closest('label').hidden=!!t?.workflowOnly;};
 const render=()=>{
 $('chooserIndustryChips').innerHTML=data.industries.filter(supports).map(i=>`<button data-project-industry="${esc(i.id)}" class="${industry===i.id?'active':''}" aria-pressed="${industry===i.id}">${esc(i.name)}</button>`).join('');
 document.querySelectorAll('[data-project-industry]').forEach(b=>b.onclick=()=>chooseIndustry(b.dataset.projectIndustry));
 $('chooserStepType').classList.toggle('active',!!industry);$('chooserTypesTitle').textContent=industry?industryName(industry)+' · 模板类型':'选择模板类型';$('chooserTypesHint').textContent=industry?'动作与视频方向在模板内部配置。':'先选择行业，再查看适用方案。';
 $('chooserTypes').innerHTML=data.templateTypes.filter(t=>t.industryId===industry&&(!requestedGroup||requestedGroup.variantIds.includes(t.id))).map(t=>`<button class="chooser-type-card ${selected===t.id?'selected':''}" data-project-type="${esc(t.id)}" aria-pressed="${selected===t.id}"><div class="chooser-type-image"><img src="${esc(t.image)}" alt="方案示意"><span>${t.workflowOnly?'人物、商品与口播':t.special?'行业特色':esc(t.categoryName||'制作方案')}</span><b aria-hidden="true">${selected===t.id?'✓':'○'}</b></div><div class="chooser-type-copy"><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><small>${t.workflowOnly?'完整口播流程':t.actionIds.length+' 个动作'} · ${esc(t.materials)}</small></div></button>`).join('')||'<div class="industry-empty"><h3>先选择你的行业</h3><p>也可以输入并新增你的行业。</p></div>';
 document.querySelectorAll('[data-project-type]').forEach(b=>b.onclick=()=>{selected=b.dataset.projectType;const t=typeById(selected);if(!$('newProjectName').dataset.edited){autoName=industryName(industry)+t.name+'制作';$('newProjectName').value=autoName;}render();});update();};
 $('newProjectName').oninput=()=>{$('newProjectName').dataset.edited='true';update();};
 if($('addIndustryForm'))$('addIndustryForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button'),name=$('newIndustryName').value.trim();if(!name){$('industryFeedback').textContent='请先输入行业名称。';return;}try{button.disabled=true;const saved=await post('/studio/industries',{name});data=await api('/studio');requestedGroup=data.templateGroups.find(g=>g.id===requestedGroup?.id);$('newIndustryName').value='';$('industryFeedback').textContent='已保存：'+saved.name;chooseIndustry(saved.id);}catch(error){$('industryFeedback').textContent=error.message;}finally{button.disabled=false;}};
 $('enterProject').onclick=()=>{const t=typeById(selected);if(!t)return;if(t.workflowOnly){const group=data.templateGroups.find(g=>g.variantIds.includes(t.id));showSharedTypeDetail(group,industry);return;}if(!$('newProjectName').value.trim())return;$('enterProject').disabled=true;location.assign(productionUrl(t)+'&direction='+encodeURIComponent(params.get('direction')||'')+'&name='+encodeURIComponent($('newProjectName').value.trim()));};
 if(industry)chooseIndustry(industry);else render();
}
function sharedGroupUrl(group,industry){return '/studio?new=1&group='+encodeURIComponent(group.id)+(industry?'&industry='+encodeURIComponent(industry):'');}
function sharedTypeCard(group,industry){
 const variant=group.variantIds.map(typeById).find(t=>t&&t.industryId===industry);
 const applicable=industry?industryName(industry):group.shared?'各行业通用':group.industryIds.map(industryName).join('、');
 return `<article class="type-card" data-type-card="${esc(group.id)}"><div class="type-cover"><img src="${esc(group.image)}" alt="${esc(group.name)}示意"><span>${group.special?'行业特色':group.shared?'通用类型':'我的方案'}</span></div><div class="type-copy"><h3>${esc(group.name)}</h3><p>${esc(group.description)}</p><div class="type-meta"><span class="type-industry">${esc(applicable)}</span><span>${group.workflowOnly?'人物、商品与口播':variant?variant.actionIds.length+' 个可选动作':'进入项目后配置动作'}</span></div>${workflowRecipeLinks(group,industry)}<div class="type-buttons"><button data-group-detail="${esc(group.id)}">查看详情</button><a class="button primary" href="${sharedGroupUrl(group,industry)}">${group.workflowOnly?'选择行业查看流程':'使用此模板'}</a></div></div></article>`;
}
function workflowRecipeLinks(group,industry){if(['service','avatar-talk'].includes(group?.categoryId))return "";
 const recipes=group?.workflowRecipes||[];if(!recipes.length)return '';
 return `<div class="workflow-recipe-links"><strong>视频方向 <span class="badge">可用于制作</span></strong><div>${recipes.map(r=>`<button data-recipe-link="${esc(r.id)}" data-recipe-industry="${esc(industry||'')}">${esc(r.name)} ↗</button>`).join('')}</div></div>`;
}
function workflowRecipeDetails(group){
 if(group.categoryId==='service')return '';
 const recipes=group.workflowRecipes||[];if(!recipes.length)return '';
 return `<section class="workflow-recipes"><h3>${group.categoryId==='avatar-talk'?'数字人商品口播':'视频方向'}</h3><p class="notice">选择行业后进入制作台，添加产品、人物与场景素材，确认文案和生成参数，再制作视频。</p>${recipes.map(r=>`<details data-workflow-recipe="${esc(r.id)}"><summary><strong>${esc(r.name)}</strong><span class="badge">可制作</span></summary><p>${esc(r.summary)}</p><p><strong>所需素材：</strong>${r.inputs.map(esc).join('；')}</p><ol><li>添加真实素材与确认过的产品卖点</li><li>生成或选择人物与商品合成关键帧</li><li>确认文案、动作与每条视频时长</li><li>重新选择服务、比例、画质与图片用途</li><li>可选试片，或按动作数量生成视频</li></ol><p class="muted">当前使用应用内的短片生成流程，每条视频是一个独立成品。一镜到底为单条视频内连续镜头；不等同于跨多个任务的首尾帧接力。模型口播由视频模型生成声音，已有配音对口型须使用对应专用服务。</p><details><summary>查看来源流程参考</summary><p>${r.rules.map(esc).join(' ')}</p><p>来源模型偏好：${r.sourceModels.map(esc).join('、')}；实际使用本次选择的生成服务。</p></details></details>`).join('')}</section>`;
}function showSharedTypeDetail(group,industry){
 const variant=group.variantIds.map(typeById).find(t=>t&&t.industryId===industry)||typeById(group.variantIds[0]);
 modal(`<h2>模板详情</h2><h3>${esc(group.name)} <span class="badge">${group.special?'行业特色':group.shared?'各行业通用':'制作方案'}</span></h3><img class="big-preview" src="${esc(group.image)}" alt="方案示意"><p class="muted">示意图片，动作示例在制作台查看。</p><div class="type-detail-line"><strong>适用行业</strong><span>${group.industryIds.map(industryName).map(esc).join('、')}</span></div><p>${esc(group.description)}</p><p>${esc(group.materials)}</p><h3 ${group.workflowOnly?"hidden":""}>${industry?'当前行业动作':'动作示例'}</h3><div class="action-chips">${variant.actionIds.slice(0,industry?30:4).map(id=>`<span>${esc(templateById(id)?.name||id)}</span>`).join('')}</div><p class="notice">${group.shared?'同一个模板类型适用于不同行业，创建项目时选择行业即可，无需重复创建模板。':'特色类型只在适用行业中提供。'} ${group.workflowOnly?'此流程需要音频驱动口型，接入后才能生成。':'每个动作分别生成视频。'}</p>${workflowRecipeDetails(group)}<a class="button primary full-width" href="${sharedGroupUrl(group,industry)}">${group.workflowOnly?'选择行业查看制作流程':'使用此模板创建项目'}</a>`,true);
}

init();
